//! View DTO generation: generates DTOs/records for database views.
//!
//! Unlike table generation (which uses RDB$RELATION_FIELDS), view DTOs use
//! resolved metadata from executing `SELECT FIRST 1 * FROM view` to get the
//! actual column types after all joins and calculations.
//!
//! The DTO is generated by converting the view's fields into a synthetic
//! [`TableSchema`] and reusing the same [`Target::generate`](super::targets::Target::generate)
//! path as table entities. This guarantees that any change to a target
//! (imports, comments, package, formatting) is automatically reflected in
//! the DTO without duplicating logic.

use rsfbclient::FbError;

use super::fbtype::FbType;
use super::generator::{GenOptions, Language};
use super::targets::{
    GoTarget, GraphqlTarget, JavaTarget, OpenApiTarget, ProtobufTarget, RustTarget, Target,
    TypeScriptTarget,
};
use super::ui::{lazarus, svelte};
use crate::client::FirebirdClient;
use crate::query::{Value, query};
use crate::schema::{ColumnInfo, TableSchema};

/// A field in a generated DTO.
#[derive(Debug, Clone)]
pub struct ViewField {
    pub name: String,
    pub type_str: String,
    pub nullable: bool,
}

/// Gets the resolved metadata for a view by executing `SELECT FIRST 1 * FROM view`.
/// Returns the column names and types as resolved by the Firebird engine.
///
/// Types are resolved from the driver's column metadata (`ColumnMeta.type_name`),
/// which maps raw Firebird type codes to human-readable names. If the view
/// returns zero rows (empty), the metadata is still available from the first
/// row's column descriptors.
pub fn get_view_metadata(
    client: &mut FirebirdClient,
    view_name: &str,
) -> Result<Vec<ViewField>, FbError> {
    let sql = format!("SELECT FIRST 1 * FROM {}", view_name);
    let result = query(client, &sql)?;

    let mut fields = Vec::new();
    for (i, col) in result.columns.iter().enumerate() {
        // Prefer the driver's type metadata; fall back to value inference
        // for the rare case where type_name is a generic "TYPE_NNN" code.
        let type_str = if col.type_name.starts_with("TYPE_") {
            infer_type_from_value(result.get(0, i))
        } else {
            col.type_name.clone()
        };
        fields.push(ViewField {
            name: col.name.clone(),
            type_str,
            nullable: true, // Views are read-only, assume nullable for safety
        });
    }

    Ok(fields)
}

/// Fallback: infers a Firebird type string from an actual `Value` in the
/// result row. Used only when the driver's column metadata is unavailable.
fn infer_type_from_value(v: &Value) -> String {
    match v {
        Value::Null => "VARCHAR".to_string(),
        Value::Bool(_) => "BOOLEAN".to_string(),
        Value::Int(_) => "INTEGER".to_string(),
        Value::Float(_) => "DOUBLE PRECISION".to_string(),
        Value::Text(_) => "VARCHAR".to_string(),
        Value::Date(_) => "DATE".to_string(),
        Value::Time(_) => "TIME".to_string(),
        Value::Timestamp(_) => "TIMESTAMP".to_string(),
        Value::Binary(_) => "BLOB".to_string(),
    }
}

/// Generates DTO code for a view in the specified language.
pub fn generate_view_dto(
    client: &mut FirebirdClient,
    views: &[String],
    opts: &GenOptions,
) -> Result<String, FbError> {
    // Views are read-only projections: suppress entity annotations (Java @Entity/@Table/@Id)
    let mut opts = opts.clone();
    opts.is_view = true;

    let mut out = String::new();

    for view in views {
        let fields = get_view_metadata(client, view)?;
        if !out.is_empty() {
            out.push_str("\n\n");
        }
        out.push_str(&generate_single_view_dto(view, &fields, &opts));
    }

    Ok(out)
}

/// Generates the DTO for a single view by converting it to a synthetic
/// `TableSchema` and reusing the target's `generate` method.
fn generate_single_view_dto(view: &str, fields: &[ViewField], opts: &GenOptions) -> String {
    match opts.language {
        Language::Java => {
            let schema = view_to_schema(view, fields);
            JavaTarget.generate(&schema, &[], opts)
        }
        Language::Go => {
            let schema = view_to_schema(view, fields);
            GoTarget.generate(&schema, &[], opts)
        }
        Language::Rust => {
            let schema = view_to_schema(view, fields);
            RustTarget.generate(&schema, &[], opts)
        }
        Language::TypeScript => {
            let schema = view_to_schema(view, fields);
            TypeScriptTarget.generate(&schema, &[], opts)
        }
        Language::Protobuf => {
            let schema = view_to_schema(view, fields);
            ProtobufTarget.generate(&schema, &[], opts)
        }
        Language::OpenApi => {
            let schema = view_to_schema(view, fields);
            OpenApiTarget.generate(&schema, &[], opts)
        }
        Language::Graphql => {
            let schema = view_to_schema(view, fields);
            GraphqlTarget.generate(&schema, &[], opts)
        }
        Language::Lazarus => {
            let lazarus_fields: Vec<lazarus::LazarusField> =
                fields.iter().map(lazarus::from_view_field).collect();
            lazarus::generate_lfm(view, &lazarus_fields, true)
        }
        Language::Svelte => {
            let svelte_fields: Vec<svelte::SvelteField> =
                fields.iter().map(svelte::from_view_field).collect();
            format!("// Page component for view {} (read-only)\n", view)
                + &svelte::generate_page_for_view(view, &svelte_fields)
        }
    }
}

/// Converts view fields into a synthetic [`TableSchema`] so the same
/// `Target::generate` path can be reused. Views have no PK, FK, indexes,
/// or constraints — only columns.
fn view_to_schema(view: &str, fields: &[ViewField]) -> TableSchema {
    let columns: Vec<ColumnInfo> = fields
        .iter()
        .map(|f| {
            let fb = FbType::from_type_str(&f.type_str);
            let (type_num, sub_type, size, precision, scale) = fb.raw();
            ColumnInfo {
                name: f.name.clone(),
                type_num,
                sub_type,
                size,
                precision,
                scale,
                nullable: if f.nullable { Some(1) } else { Some(0) },
                default: None,
                position: None,
                domain: String::new(),
            }
        })
        .collect();

    TableSchema {
        table: view.to_string(),
        columns,
        indexes: Vec::new(),
        constraints: Vec::new(),
        triggers: Vec::new(),
        comments: std::collections::HashMap::new(),
    }
}
